// Package schema holds shingo-core's PostgreSQL schema as committed files, and
// the catalog predicates a migration's verify is written with.
//
//   - baseline.sql: the whole schema and its seed rows, which a new database
//     is born on (store.migrate applies it, as one statement, to a database
//     with no tables). Generated by cmd/schemabaseline (make schema-baseline):
//     the retired chain's release booted on an empty database, this tree's
//     migrations above it, then comments.sql, dumped. Never edited.
//   - comments.sql: the schema's rationale as COMMENT ON statements, which the
//     generator applies before it dumps.
//   - schema.snapshot.sql: what a fresh boot of this build ships, dumped
//     without comments or rows (cmd/schemasnapshot, make schema-snapshot), the
//     file a reviewer reads a shape change in.
//
// Until the squash at v184 this package held the baseline DDL as a Go
// constant that every boot replayed ahead of the versioned chain (Apply), and
// the predicates below served the chain's steps. The constant and Apply went
// with the chain; the predicates stay for each migration above it
// (store.migration): its verify, whose post-conditions they read, and the
// guards that make it idempotent. v185 is the first.
//
// The predicates accept the Querier interface so they work equally well with
// *sql.DB (the connection pool) and *sql.Tx (an in-flight transaction).
package schema

import (
	"database/sql"
)

// Querier is the subset of database/sql methods these helpers need.
// *sql.DB and *sql.Tx both satisfy it via Go's structural typing,
// which lets migration code use the same helpers whether it's
// running against the connection pool or inside a transaction.
type Querier interface {
	QueryRow(query string, args ...any) *sql.Row
	Exec(query string, args ...any) (sql.Result, error)
}

// Every predicate below reads schema public only, the schema Core's tables
// live in. A same-named table in another schema (a copy someone made with
// CREATE TABLE pre185.orders AS TABLE public.orders, say) is not Core's: read
// as Core's, it would make v185's verify fail on a migrated database, and the
// re-run that follows would fail on public's renamed column every boot
// (TestSchemaPredicates_ReadSchemaPublicOnly).

// TableExists reports whether the named table exists in schema public.
// Returns false on any query error (the table also "doesn't exist" if we
// can't read information_schema).
func TableExists(c Querier, table string) bool {
	var exists bool
	c.QueryRow(
		`SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name=$1)`,
		table,
	).Scan(&exists)
	return exists
}

// ColumnExists reports whether the named column exists on the named table in
// schema public. Returns false on any query error or if either name is empty.
func ColumnExists(c Querier, table, column string) bool {
	var exists bool
	c.QueryRow(
		`SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name=$1 AND column_name=$2)`,
		table, column,
	).Scan(&exists)
	return exists
}

// ColumnAbsent and IndexAbsent are the ABSENCE forms of the Exists helpers
// below, and they exist because negating those is not the same thing.
//
// The Exists helpers return false on a query error, which is the right
// direction where false means "not applied, re-run an idempotent statement".
// Written as !ColumnExists(...) to assert a DROP, that direction inverts: a
// query that could not run reports the post-condition as HOLDING, and the
// migration is recorded as applied without anything having checked. These
// return false on error, so a failed check re-runs a DROP ... IF EXISTS and
// costs nothing.
//
// Every VERIFY predicate in migrations.go asserts an absence with these, and
// TestMigrationVerifyPredicatesAssertAbsenceWithTheAbsenceHelpers keeps it that
// way. A `!ColumnExists` inside a migration BODY, guarding whether to do the
// work, has the correct direction for that job: on a failed check it attempts
// the idempotent DDL rather than skipping it. Swapping those would invert a
// check that is already right, which is why the lint keys on the parameter
// type instead of the spelling.
func ColumnAbsent(c Querier, table, column string) bool {
	var exists bool
	if err := c.QueryRow(
		`SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name=$1 AND column_name=$2)`,
		table, column,
	).Scan(&exists); err != nil {
		return false
	}
	return !exists
}

// TableAbsent is the absence form for a migration that DROPS a table. Same
// direction as ColumnAbsent: false on a query error, so a check that could not
// run re-runs an idempotent DROP ... IF EXISTS instead of recording the
// migration as applied.
func TableAbsent(c Querier, table string) bool {
	var exists bool
	if err := c.QueryRow(
		`SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name=$1)`,
		table,
	).Scan(&exists); err != nil {
		return false
	}
	return !exists
}

// IndexAbsent is the absence form for a migration that DROPS an index in
// schema public. Same direction as ColumnAbsent: false on a query error.
func IndexAbsent(c Querier, indexName string) bool {
	var exists bool
	if err := c.QueryRow(
		`SELECT EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND indexname=$1)`, indexName,
	).Scan(&exists); err != nil {
		return false
	}
	return !exists
}

// IndexExists reports whether the named index exists in schema public.
// Returns false on any query error or if the name is empty.
func IndexExists(c Querier, indexName string) bool {
	var exists bool
	c.QueryRow(
		`SELECT EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND indexname=$1)`,
		indexName,
	).Scan(&exists)
	return exists
}

// ConstraintExists reports whether the named constraint is on the named table
// in schema public, valid or not. Returns false on any query error.
func ConstraintExists(c Querier, table, constraint string) bool {
	var exists bool
	c.QueryRow(
		`SELECT EXISTS (SELECT 1 FROM pg_constraint k
		   JOIN pg_class t ON t.oid = k.conrelid
		   JOIN pg_namespace n ON n.oid = t.relnamespace
		  WHERE n.nspname = 'public' AND t.relname = $1 AND k.conname = $2)`,
		table, constraint,
	).Scan(&exists)
	return exists
}
